package com.guocheng.mediapocket;
import android.app.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Grouped real site-search results; no media is changed until a result is selected. */
final class SourcePickerDialog {
 interface Pick {void selected(FusionCatalog.Session session,JSONObject item);}
 final Activity a;final FusionCatalog.Session base;final Pick pick;final boolean light;final int ink,muted,bg;final ExecutorService pool=Executors.newFixedThreadPool(2);final ArrayList<Group> groups=new ArrayList<>();final Dialog dialog;final TextView summary;final EditText query;boolean closed;int generation;
 final class Group {JSONObject site;TextView header;LinearLayout content;JSONArray results=new JSONArray();String status="等待搜索";boolean expanded;int request;Future<?> task;FusionCatalog.Session session;}
 int dp(int n){return (int)(n*a.getResources().getDisplayMetrics().density+.5f);}
 TextView text(String s,int size){TextView t=new TextView(a);t.setText(s);t.setTextSize(size);t.setTextColor(ink);t.setPadding(dp(12),dp(12),dp(12),dp(12));return t;}
 Button button(String label,Runnable action){Button b=new Button(a);b.setText(label);b.setTextColor(ink);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(v->action.run());return b;}
 SourcePickerDialog(Activity owner,FusionCatalog.Session initial,String title,Pick callback){a=owner;base=initial;pick=callback;light=a.getSharedPreferences("data",0).getString("themeMode","dark").equals("light");boolean goldUi=!light&&CinemaTheme.gold(a);ink=light?0xff202830:goldUi?CinemaTheme.INK:0xfff1f4f6;muted=light?0xff697580:goldUi?CinemaTheme.MUTED:0xffb0c1cc;bg=light?0xfffafbfc:goldUi?CinemaTheme.CARD:0xff16343e;dialog=new Dialog(a);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setPadding(dp(10),dp(6),dp(10),dp(14));GradientDrawable shape=new GradientDrawable();shape.setColor(bg);shape.setCornerRadius(dp(24));root.setBackground(shape);TextView handle=text("━━",14);handle.setGravity(Gravity.CENTER);handle.setTextColor(muted);root.addView(handle);LinearLayout top=new LinearLayout(a);TextView heading=text("播放来源",22);heading.setTypeface(null,1);top.addView(heading,new LinearLayout.LayoutParams(0,-2,1));top.addView(button("关闭",()->dialog.dismiss()));root.addView(top);summary=text("正在准备来源…",12);summary.setTextColor(muted);root.addView(summary);LinearLayout search=new LinearLayout(a);query=new EditText(a);query.setSingleLine(true);query.setText(title);query.setTextColor(ink);query.setHint("输入片名");query.setHintTextColor(muted);search.addView(query,new LinearLayout.LayoutParams(0,-2,1));search.addView(button("搜索",()->start()));root.addView(search);ScrollView scroll=new ScrollView(a);LinearLayout list=new LinearLayout(a);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));JSONArray sites=base.config.optJSONArray("sites");for(int i=0;sites!=null&&i<sites.length();i++){JSONObject site=sites.optJSONObject(i);if(site==null)continue;Group g=new Group();g.site=site;LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);g.header=text("",14);g.header.setOnClickListener(v->{g.expanded=!g.expanded;render(g);});row.addView(g.header,new LinearLayout.LayoutParams(0,-2,1));row.addView(button("⋮",()->new AlertDialog.Builder(a).setItems(new String[]{"重新搜索此来源","查看状态"},(d,n)->{if(n==0)search(g,generation,query.getText().toString().trim());else new AlertDialog.Builder(a).setTitle(g.site.optString("name")).setMessage(g.status).setPositiveButton("关闭",null).show();}).show()));list.addView(row);g.content=new LinearLayout(a);g.content.setOrientation(1);list.addView(g.content);View line=new View(a);line.setBackgroundColor(light?0xffe7ebee:0xff294752);list.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));groups.add(g);render(g);}dialog.setContentView(root);dialog.setOnDismissListener(d->{closed=true;generation++;for(Group g:groups)if(g.task!=null)g.task.cancel(true);pool.shutdownNow();});dialog.show();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);int width=a.getResources().getDisplayMetrics().widthPixels,height=a.getResources().getDisplayMetrics().heightPixels;w.setLayout(Math.min(width-dp(16),dp(640)),(int)(height*.84));w.setGravity(width<dp(600)?Gravity.BOTTOM:Gravity.CENTER);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams lp=w.getAttributes();lp.dimAmount=.5f;w.setAttributes(lp);}start();}
 boolean valid(int token){return !closed&&!a.isFinishing()&&!a.isDestroyed()&&generation==token;}
 void start(){if(closed)return;String word=query.getText().toString().trim();if(word.isEmpty()){query.setError("请输入片名");return;}int token=++generation;for(Group g:groups)search(g,token,word);}
 void search(Group g,int token,String word){if(closed||word.isEmpty())return;if(g.task!=null)g.task.cancel(true);int request=++g.request;g.results=new JSONArray();g.expanded=false;if(g.site.optInt("type",3)!=3||g.site.optInt("searchable",1)==0){g.status="不支持搜索";render(g);return;}g.status="等待搜索";render(g);g.task=pool.submit(()->{if(!valid(token))return;a.runOnUiThread(()->{if(valid(token)&&request==g.request){g.status="搜索中…";render(g);}});try{FusionCatalog.Session session=new FusionCatalog.Session(base.url,base.config,g.site);JSONArray result=SourceSearchClient.run(a,session,word,25000);a.runOnUiThread(()->{if(!valid(token)||request!=g.request)return;g.session=session;g.results=result==null?new JSONArray():result;g.status=g.results.length()==0?"无结果":g.results.length()+" 个结果";g.expanded=g.results.length()>0;render(g);});}catch(Exception e){String reason=SourceSearchClient.reason(e);a.runOnUiThread(()->{if(!valid(token)||request!=g.request)return;g.status="搜索失败 · "+reason;render(g);});}});}
 void render(Group g){g.header.setText(g.site.optString("name",g.site.optString("key"))+"\n"+(g.status.startsWith("搜索失败")?"搜索失败":g.status)+"  "+(g.expanded?"⌃":"⌄"));g.content.removeAllViews();if(g.expanded){for(int i=0;i<Math.min(100,g.results.length());i++){JSONObject item=g.results.optJSONObject(i);if(item==null)continue;String label=item.optString("vod_name")+"  "+item.optString("vod_year")+"  "+item.optString("vod_remarks")+"   ▶";Button b=button(label,()->{FusionCatalog.Session s=g.session;dialog.dismiss();pick.selected(s,item);});b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);g.content.addView(b,new LinearLayout.LayoutParams(-1,-2));}if(g.results.length()==0){TextView status=text(g.status,12);status.setTextColor(muted);g.content.addView(status);}}int count=0,done=0;for(Group x:groups){count+=x.results.length();if(!x.status.equals("等待搜索")&&!x.status.equals("搜索中…"))done++;}summary.setText(groups.size()+" 个来源 · "+count+" 个候选结果 · 已完成 "+done+"/"+groups.size());}
}
